SELECT  FROM agent_conversation_elicitation
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND request_id = #{requestId}

SELECT  FROM agent_conversation_elicitation
WHERE tenant_id = #{tenantId}
  AND turn_id = #{turnId}
  AND status = 'PENDING'
ORDER BY id ASC

SELECT  FROM agent_conversation_elicitation
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND status = 'PENDING'
ORDER BY id ASC

mapper.update:
UPDATE agent_conversation_elicitation
SET status = #{status},
    answer_json = #{answerJson},
    gmt_modified = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND request_id = #{requestId}
  AND status = 'PENDING'

UPDATE agent_conversation_elicitation
SET status = 'PENDING',
    answer_json = NULL,
    gmt_modified = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND request_id = #{requestId}
  AND status = #{expectedStatus}

mapper.select:
SELECT  FROM agent_conversation_elicitation
WHERE status = 'PENDING'
  AND gmt_create < #{cutoff}
ORDER BY id ASC
LIMIT #{limit}
